INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
('b0000000-0000-0000-0009-000000000000', '유니크 키(Unique key)와 기본 키의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000001', '외래 키(Foreign Key)는 무엇이며, 왜 사용하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000002', '인덱스(Index)란 무엇이며, 성능에 어떤 영향을 주나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000003', '트랜잭션(Transaction)이란 무엇이고 ACID는 무엇을 의미하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000004', 'Commit과 Rollback의 차이는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000005', 'MySQL에서 잠금(Lock)은 어떤 종류가 있고, 언제 걸리나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000006', 'MyISAM과 InnoDB 스토리지 엔진의 차이는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000007', 'InnoDB에서 외래 키 지원과 트랜잭션이 되는 이유는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000008', '정규화(Normalization)란 무엇이며, 1NF/2NF/3NF를 설명해 보세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000009', 'JOIN의 종류에는 무엇이 있고, 각각 어떻게 동작하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000010', 'INNER JOIN과 OUTER JOIN의 차이를 설명해 주세요.', 'EASY', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000011', 'GROUP BY와 HAVING절은 언제 사용하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000012', '서브쿼리(Subquery)란 무엇이며, 어떤 경우에 유용한가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000013', '뷰(View)란 무엇이고, 사용상의 장단점은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000014', '스토어드 프로시저(Stored Procedure)는 무엇이며 왜 사용하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000015', '트리거(Trigger)란 무엇이고, 언제 활용할 수 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000016', 'MySQL에서 풀텍스트 검색(Full-text Search)은 어떻게 구현되나요?', 'HARD', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000017', '쿼리 최적화를 위해 실행 계획(EXPLAIN)은 어떻게 활용하나요?', 'HARD', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000018', '복제(Replication)란 무엇이며, MySQL에서 어떻게 설정하나요?', 'HARD', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000019', 'MySQL에서 마스터-슬레이브 복제의 원리는 무엇인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000020', 'MySQL 8.x 버전에서 달라진 점이나 새로운 기능은 무엇인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000021', 'NoSQL vs MySQL: 어느 상황에서 관계형 DB 대신 NoSQL을 고려하시겠습니까?', 'HARD', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000022', '대용량 테이블에서 성능 튜닝을 위해 해본 작업이 있다면 소개해 보세요.', 'HARD', 'b0000000-0000-0000-0000-000000000009'),
('b0000000-0000-0000-0009-000000000023', '운영 중인 MySQL에서 슬로우 쿼리가 발견되면 어떻게 대응하나요?', 'HARD', 'b0000000-0000-0000-0000-000000000009');
